### Describe the feature you'd like

-- ============================================================
-- POINT
-- ============================================================

CREATE TABLE test_point (
    id INT PRIMARY KEY AUTO_INCREMENT,
    location POINT
);

INSERT INTO test_point(location) VALUES (ST_GeomFromText('POINT(116.397428 39.90923)'));
INSERT INTO test_point(location) VALUES (ST_GeomFromText('POINT(121.473701 31.230416)'));

SELECT id, ST_AsText(location) FROM test_point;
SELECT ST_Distance(
    (SELECT location FROM test_point WHERE id = 1),
    (SELECT location FROM test_point WHERE id = 2)
);
SELECT ST_X(location), ST_Y(location) FROM test_point WHERE id = 1;

DROP TABLE test_point;


-- ============================================================
-- GEOMETRY（通用类型，可存任意几何对象）
-- ============================================================

CREATE TABLE test_geometry (
    id INT PRIMARY KEY AUTO_INCREMENT,
    geom GEOMETRY
);

INSERT INTO test_geometry(geom) VALUES (ST_GeomFromText('POINT(1 2)'));
INSERT INTO test_geometry(geom) VALUES (ST_GeomFromText('LINESTRING(0 0, 3 4)'));
INSERT INTO test_geometry(geom) VALUES (ST_GeomFromText('POLYGON((0 0,1 0,1 1,0 1,0 0))'));

-- POINT 列只能存 POINT，GEOMETRY 列可以混存
SELECT id, ST_GeometryType(geom), ST_AsText(geom) FROM test_geometry;
SELECT id, ST_SRID(geom) FROM test_geometry;

DROP TABLE test_geometry;

-- ============================================================
-- LINESTRING
-- ============================================================

CREATE TABLE test_linestring (
    id INT PRIMARY KEY AUTO_INCREMENT,
    path LINESTRING
);

INSERT INTO test_linestring(path) VALUES (ST_GeomFromText('LINESTRING(0 0, 1 1, 2 2)'));
INSERT INTO test_linestring(path) VALUES (ST_GeomFromText('LINESTRING(0 0, 5 0, 5 5, 0 5)'));

SELECT id, ST_AsText(path) FROM test_linestring;
SELECT id, ST_Length(path) FROM test_linestring;

DROP TABLE test_linestring;


-- ============================================================
-- POLYGON
-- ============================================================

CREATE TABLE test_polygon (
    id INT PRIMARY KEY AUTO_INCREMENT,
    area POLYGON
);

INSERT INTO test_polygon(area) VALUES (ST_GeomFromText('POLYGON((0 0, 10 0, 10 10, 0 10, 0 0))'));
INSERT INTO test_polygon(area) VALUES (ST_GeomFromText('POLYGON((0 0, 20 0, 20 20, 0 20, 0 0), (5 5, 15 5, 15 15, 5 15, 5 5))'));

SELECT id, ST_AsText(area) FROM test_polygon;
SELECT id, ST_Area(area) FROM test_polygon;
SELECT ST_Contains(
    (SELECT area FROM test_polygon WHERE id = 1),
    ST_GeomFromText('POINT(5 5)')
);

DROP TABLE test_polygon;


-- ============================================================
-- MULTIPOINT
-- ============================================================

CREATE TABLE test_multipoint (
    id INT PRIMARY KEY AUTO_INCREMENT,
    points MULTIPOINT
);

INSERT INTO test_multipoint(points) VALUES (ST_GeomFromText('MULTIPOINT((0 0),(1 1),(2 2))'));

SELECT id, ST_AsText(points) FROM test_multipoint;
SELECT id, ST_NumGeometries(points) FROM test_multipoint;

DROP TABLE test_multipoint;


