CREATE TABLE test_multipolygon (
    id INT PRIMARY KEY AUTO_INCREMENT,
    areas MULTIPOLYGON
);

INSERT INTO test_multipolygon(areas) VALUES (ST_GeomFromText('MULTIPOLYGON(((0 0,10 0,10 10,0 10,0 0)),((20 20,30 20,30 30,20 30,20 20)))'));

SELECT id, ST_AsText(areas) FROM test_multipolygon;
SELECT id, ST_Area(areas) FROM test_multipolygon;

DROP TABLE test_multipolygon;


