-- GEOMETRYCOLLECTION
-- ============================================================

CREATE TABLE test_geomcollection (
    id INT PRIMARY KEY AUTO_INCREMENT,
    geom GEOMETRYCOLLECTION
);

INSERT INTO test_geomcollection(geom) VALUES (ST_GeomFromText('GEOMETRYCOLLECTION(POINT(1 1),LINESTRING(0 0,1 1,2 2),POLYGON((0 0,5 0,5 5,0 5,0 0)))'));

SELECT id, ST_AsText(geom) FROM test_geomcollection;
SELECT id, ST_NumGeometries(geom) FROM test_geomcollection;
SELECT id, ST_GeometryN(geom, 1) FROM test_geomcollection;

DROP TABLE test_geomcollection;


