SELECT id, ST_SRID(geom) FROM test_geometry;

DROP TABLE test_geometry;

-- ============================================================
-- POINT SRID 4326
-- ============================================================

CREATE TABLE geo_srid (
   id INT PRIMARY KEY,
   location POINT NOT NULL SRID 4326
);

INSERT INTO geo_srid VALUES (1, ST_GeomFromText('POINT(116.397428 39.90923)', 4326));
SELECT ST_SRID(location) FROM geo_srid;
-- Expected: 4326

-- Mismatched SRID should error
INSERT INTO geo_srid VALUES (2, ST_GeomFromText('POINT(0 0)', 0));
-- Expected: error (SRID mismatch)

